'use strict';
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalogue,health;let aiSessionStatus='unverified';const selected=new Set();let activePage='overview',labRows=[],currentAnswer=null;let explorerView='cards',chartMetric='conditions';let searchTimer;let searchVersion=0;const drafts={};const selectedTests=new Set();let pendingAsk=false;
function remember(){drafts[activePage]=Object.fromEntries([...document.querySelectorAll('#page input,#page select,#page textarea')].filter(e=>!e.dataset.select&&!e.dataset.testSelect).map(e=>[e.id||e.name,{value:e.value,checked:e.checked}]));}
function restore(){for(const e of document.querySelectorAll('#page input,#page select,#page textarea')){const d=drafts[activePage]?.[e.id||e.name];if(d){e.value=d.value;e.checked=d.checked;}}}
function passageHTML(items){return items?.length?'<h3>Supporting source passages</h3>'+items.map(p=>'<article class="source-card"><strong>'+esc(p.title)+'</strong><p>'+esc(p.text)+'</p><span class="note">'+esc(p.kind)+' · '+esc(p.location)+'</span><div>'+sourceLink(p.source)+(p.page?' · <a target="_blank" rel="noopener noreferrer" href="'+esc(getSource(p.source).url)+'#page='+p.page+'">Open page '+p.page+' ↗</a>':'')+'</div></article>').join(''):'';}

const titles={overview:'Mission briefing',insights:'Mission insights',dashboard:'Dashboard',explorer:'Evidence archive',compare:'Compare evidence',lab:'Data laboratory',scenario:'Mission scenario',assistant:'Ask the evidence',sources:'Sources & context',method:'Methodology'};
const getInv=id=>catalogue.investigations.find(i=>i.id===id);const getSource=id=>catalogue.sources.find(s=>s.id===id);const badge=(cat)=>`<span class="badge ${esc(cat.toLowerCase())}">${esc(cat)}</span>`;
const safeSourceURL=source=>{try{const url=new URL(source.url);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}};
const sourceLink=id=>{const source=getSource(id);const url=source&&safeSourceURL(source);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`:'';};
function aiStatusText(){if(!health.aiConfigured)return 'Evidence retrieval mode';if(aiSessionStatus==='success')return 'AI verified this session';if(aiSessionStatus==='fallback')return 'Last AI request used fallback';return 'AI configured · not yet tested';}
function renderAnswerText(answer,citations=[]){
 const allowed=new Set(citations);let html='',offset=0;const text=String(answer??'');
 for(const match of text.matchAll(/\[([a-z0-9-]+)\]/g)){
  html+=esc(text.slice(offset,match.index));const source=getSource(match[1]);const url=source&&allowed.has(match[1])&&safeSourceURL(source);
  html+=url?`<a class="inline-citation" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="Open source: ${esc(source.title)}">[${citations.indexOf(match[1])+1}]</a>`:esc(match[0]);offset=match.index+match[0].length;
 }
 return html+esc(text.slice(offset));
}

const head=(eyebrow,title,sub,action='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
async function request(path,options){const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function saveFile(name,body,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000);}
function evidenceStatus(i){const rows=catalogue.tests.filter(t=>t.investigation===i.id);return rows.some(t=>t.verification==='Report verified')?'<span class="badge verified">Report-verified</span>':rows.length?'<span class="badge warning source-transcribed">Source-transcribed · interpretation pending</span>':(i.findings?.length?'<span class="badge source-located">Source-located findings</span>':'<span class="badge context">Context only</span>');}
function resultsChart(rows,metric='spread_rate_mms'){const valid=rows.filter(t=>t.verification==='Report verified'&&t[metric]!=null);const max=Math.max(...valid.map(t=>t[metric]),1);const unit=metric==='spread_rate_mms'?'mm/s':'s';return '<div class="result-bars" aria-label="Reported '+(metric==='spread_rate_mms'?'flame spread rates':'burn durations')+'">'+valid.map(t=>'<button class="result-bar" data-test="'+esc(t.id)+'" data-highlight="'+esc(t.id)+'" title="'+esc(t.raw_material)+'; airflow '+t.airflow_cms+' cm/s; initial oxygen '+t.oxygen_initial_pct+'%; '+esc(t.measurement_location)+'"><span>'+esc(t.id)+'</span><span class="bar-track"><span class="bar-fill combustion-bar" style="width:'+t[metric]/max*100+'%"></span></span><strong>'+t[metric]+' '+unit+'</strong></button>').join('')+'</div>';}
function overviewResults(){return '<section class="panel primary-results"><div class="split-title"><div><div class="eyebrow">EXPERIMENTAL RESULTS / SAFFIRE</div><h2>Reported flame spread rates</h2></div><a href="#lab" class="text-link">Open laboratory →</a></div><p>Report-verified measurements · mm/s · select a bar to inspect its record.</p>'+resultsChart(catalogue.tests)+'<p class="note">Sample size, oxygen and airflow differ. These observations do not establish a controlled causal comparison.</p></section>';}
function card(i,extra=''){return `<article class="card"><div class="split-title">${badge(i.category)}<span class="muted micro">${esc(i.psi||i.platform)}</span></div><h3>${esc(i.name)}</h3><p>${esc(i.summary)}</p><div class="evidence-status">${evidenceStatus(i)}</div><div class="meta">${esc(i.gravity)} · ${esc(i.fuel)}<br>${esc(i.coverage)}</div>${extra}<div class="card-bottom"><button class="text-button" data-detail="${i.id}">View evidence ↗</button><label class="check"><input type="checkbox" data-select="${i.id}" ${selected.has(i.id)?'checked':''}>Compare</label></div></article>`;}
function comparisonBar(){return selected.size?`<div class="compare-bar"><span>${selected.size} investigations selected</span><a class="button secondary" href="#compare">Compare selected →</a></div>`:'';}
function researchPhotos(){return `<section class="research-photography" aria-label="NASA combustion research imagery"><figure class="flame-photo"><img src="https://svs.gsfc.nasa.gov/vis/a010000/a011300/a011318/pf2-1024.jpg" alt="NASA imagery comparing a candle flame on Earth with a rounded flame in microgravity" width="1024" height="576" decoding="async"><figcaption><span class="eyebrow">FLAMES IN MICROGRAVITY</span><h2>A different environment. A different flame.</h2><p>NASA imagery introduces the combustion research behind the catalogue. These images are context, not measurements from the plotted records.</p><a href="https://svs.gsfc.nasa.gov/11318" target="_blank" rel="noopener noreferrer">Image credit: Science@NASA / NASA Goddard ↗</a></figcaption></figure><figure class="station-photo"><img src="https://svs.gsfc.nasa.gov/vis/a010000/a011300/a011318/s1l-1024.jpg" alt="NASA view of the International Space Station with the Destiny module indicated" width="1024" height="576" loading="lazy" decoding="async"><figcaption><span class="eyebrow">THE ORBITING LABORATORY</span><h3>Research aboard the ISS</h3><p>The Destiny module hosts FLEX research.</p><a href="https://svs.gsfc.nasa.gov/11318" target="_blank" rel="noopener noreferrer">NASA / Goddard · View source ↗</a></figcaption></figure></section>`;}
function dashboardInsights(){const top=(catalogue.insights||[]).slice(0,3);const cells=['Prevention','Detection','Suppression','Fundamentals'].length*2;return '<section class="dash-insights"><div class="split-title"><div><div class="eyebrow">TOP INSIGHTS · RANKED BY EVIDENCE STRENGTH</div><h2>What the evidence says</h2></div><a class="text-link" href="#insights">All '+(catalogue.insights||[]).length+' insights →</a></div><div class="dash-insight-row">'+top.map((s,n)=>'<a class="dash-insight" href="#insights"><b>'+(n+1)+'</b>'+badge(s.theme)+'<h3>'+esc(s.title)+'</h3><span class="micro muted">Strength '+s.strength.score+' · '+esc(strengthText(s.strength))+'</span></a>').join('')+'<a class="dash-insight dash-gap" href="#insights"><b>0</b><span class="badge context">Moon & Mars</span><h3>direct records in '+cells+' of '+cells+' partial-gravity cells.</h3><span class="micro muted">Every record here is microgravity evidence. See the gap matrix →</span></a></div></section>';}
function overview(){const categories=['Prevention','Detection','Suppression','Fundamentals'];const verified=catalogue.tests.filter(t=>t.verification==='Report verified').length;const csv=catalogue.tests.length-verified;return head('DASHBOARD / AT A GLANCE','The whole collection on one screen.','Measurements, coverage, top insights and the Moon/Mars gap. Every number opens its source.',`<a class="button" href="#insights">Read the ranked insights →</a>`)+`${dashboardInsights()}${overviewResults()}<section class="stats compact-stats" aria-label="Catalogue coverage">${[[catalogue.investigations.length,'Investigations','Four research themes'],[catalogue.tests.length,'Test records',verified+' report-verified · '+csv+' source CSV'],[(catalogue.quantitativeFindings||[]).length,'Report findings','Quantitative, source-located'],[catalogue.sources.length,'Source references','Access status documented']].map(([n,t,d])=>`<div class="stat"><span class="label">${t}</span><strong>${n}</strong><small>${d}</small></div>`).join('')}</section><div class="dashboard-grid"><section class="panel collection-chart"><div class="split-title"><div><div class="eyebrow">RESEARCH COVERAGE</div><h2>Investigations by theme</h2></div><span class="pill">${catalogue.investigations.length} entries</span></div><p>Catalogue composition, not a ranking of fire risk.</p><div class="theme-bars">${categories.map((c,index)=>{const n=catalogue.investigations.filter(i=>i.category===c).length;return `<div class="theme-row"><span><i class="theme-key theme-${index}"></i>${c}</span><div class="bar-track"><div class="bar-fill theme-${index}" style="width:${n/catalogue.investigations.length*100}%"></div></div><strong>${n}</strong></div>`;}).join('')}</div><a class="text-link" href="#explorer">Open investigation catalogue →</a></section><section class="panel coverage-panel"><div class="eyebrow">DATA AVAILABILITY</div><h2>Know what is included.</h2><div class="coverage-total"><strong>${catalogue.tests.length}</strong><span>individual test records</span></div><div class="coverage-stack" role="img" aria-label="${verified} report-verified records and ${csv} source-transcribed records"><span style="width:${verified/catalogue.tests.length*100}%"></span><span style="width:${csv/catalogue.tests.length*100}%"></span></div><div class="coverage-line"><span>Report-verified Saffire</span><strong>${verified}</strong></div><div class="coverage-line"><span>Source-transcribed BASS-II</span><strong>${csv}</strong></div><p class="note">CSV transcription is checked. Sensor interpretation and fan calibration review remain pending.</p><a class="text-link" href="#lab">Inspect the measurements →</a></section></div><div class="section-head"><div><div class="eyebrow">SELECTED INVESTIGATIONS</div><h2>Three perspectives on spacecraft fire</h2></div><a href="#explorer">View catalogue →</a></div><div class="grid">${['bass2','same','flex'].map(id=>card(getInv(id))).join('')}</div><section class="research-banner"><div><h2>Explore a habitat research scenario</h2><p>Compare material, oxygen and airflow conditions with the available evidence.</p></div><a class="button secondary" href="#scenario">Open scenario explorer →</a></section><div class="notice blue">Curated subset: ${verified} Saffire records and ${csv} BASS-II records. No direct lunar or Martian partial-gravity data is included. <a href="#method">Review scope and limitations →</a></div>`+comparisonBar();}
function briefing(){const verified=catalogue.tests.filter(t=>t.verification==='Report verified').length;const csv=catalogue.tests.length-verified;return `<section class="mission-hero"><div class="hero-copy"><div class="eyebrow">NASA COMBUSTION EVIDENCE / HUMAN SPACEFLIGHT</div><p class="hero-kicker">A mission briefing for a problem that cannot wait.</p><h1>Fire changes when gravity disappears.</h1><p class="hero-lede">FlameWise helps you follow NASA's microgravity combustion evidence - from a mission question to the studies, conditions and limits that matter.</p><div class="hero-actions"><a class="button" href="#scenario">Start a mission scenario <span>→</span></a><a class="quiet-link" href="#dashboard">Open the dashboard</a><a class="quiet-link" href="#explorer">Browse the evidence archive</a></div><p class="hero-proof"><span></span> Real NASA records. Clear source trails. No invented certainty.</p></div><div class="flame-field gl-stage"></div></section><section class="gravity-lab" aria-labelledby="gravity-lab-title"><div class="gravity-lab-copy"><div class="eyebrow">WHAT YOU JUST WATCHED</div><h2 id="gravity-lab-title">Same fuel. Two completely different fires.</h2><p>On Earth, hot gas rises and pulls fresh air in at the base, stretching the flame into a bright teardrop. Aboard the ISS nothing rises: oxygen only creeps in by diffusion, so the flame becomes a dim, slow, blue sphere. The Moon and Mars sit in between, and that is exactly where this collection has no records.</p></div><div class="diptych-stage"><svg class="flame-diptych" viewBox="0 0 560 500" role="img" aria-label="Side by side: on Earth a tall teardrop flame with hot gas rising; in microgravity a dim blue spherical flame with oxygen diffusing in from all sides"><defs><linearGradient id="earth-outer" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#ff5a2e"/><stop offset=".45" stop-color="#ff9a3c"/><stop offset="1" stop-color="#ffd36d" stop-opacity=".15"/></linearGradient><linearGradient id="earth-core" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stop-color="#fff4d6"/><stop offset=".7" stop-color="#ffe08a"/><stop offset="1" stop-color="#ffd36d" stop-opacity="0"/></linearGradient><radialGradient id="micro-shell"><stop offset="0" stop-color="#0b1a33" stop-opacity="0"/><stop offset=".55" stop-color="#2a5fd6" stop-opacity=".18"/><stop offset=".78" stop-color="#5b95ff" stop-opacity=".95"/><stop offset=".9" stop-color="#8fb8ff" stop-opacity=".5"/><stop offset="1" stop-color="#8fb8ff" stop-opacity="0"/></radialGradient><filter id="soft" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="9"/></filter><filter id="softer"><feGaussianBlur stdDeviation="2.5"/></filter><marker id="tip" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L8 4L0 8z" fill="#8cdddc"/></marker></defs>
<g class="earth-side"><g class="buoyancy" stroke="#ffb36b" stroke-width="1.4" fill="none" stroke-linecap="round" marker-end="url(#tip)"><path d="M92 300V230"/><path d="M228 300V230" style="animation-delay:.8s"/><path d="M160 120V62" style="animation-delay:1.5s"/></g><path class="flame-glow" d="M160 410C98 410 88 330 118 272C140 230 158 182 160 96C164 182 186 232 204 276C232 338 222 410 160 410Z" fill="#ff6a3d" filter="url(#soft)"/><path class="flame-path" d="M160 404C112 404 102 336 126 284C145 243 158 196 160 112C163 196 178 244 196 286C220 340 210 404 160 404Z" fill="url(#earth-outer)"/><path class="flame-core" d="M160 398C136 398 131 360 143 330C152 307 159 280 160 236C162 280 170 306 178 330C189 362 184 398 160 398Z" fill="url(#earth-core)"/><ellipse cx="160" cy="392" rx="22" ry="11" fill="#3c7bff" opacity=".75" filter="url(#softer)"/><path d="M160 398V424" stroke="#c9d2de" stroke-width="3" stroke-linecap="round"/><text x="160" y="458" text-anchor="middle" class="svg-label">EARTH · 1 g</text><text x="160" y="476" text-anchor="middle" class="svg-sub">Hot gas rises · fresh air pulled in</text></g>
<path d="M248 270C288 248 318 248 352 266" stroke="#8cdddc" stroke-width="1" stroke-dasharray="4 5" fill="none" marker-end="url(#tip)"/><text x="300" y="236" text-anchor="middle" class="svg-sub">remove gravity</text>
<g class="micro-side"><g class="diffusion" fill="#8cdddc">${[0,45,90,135,180,225,270,315].map((a,n)=>`<circle r="2.4" cx="${(420+Math.cos(a*Math.PI/180)*128).toFixed(1)}" cy="${(280+Math.sin(a*Math.PI/180)*128).toFixed(1)}" style="--dx:${(-Math.cos(a*Math.PI/180)*44).toFixed(1)}px;--dy:${(-Math.sin(a*Math.PI/180)*44).toFixed(1)}px;animation-delay:${(n*.35).toFixed(2)}s"/>`).join('')}</g><circle class="micro-glow" cx="420" cy="280" r="96" fill="#3f78ff" opacity=".22" filter="url(#soft)"/><circle class="micro-flame" cx="420" cy="280" r="84" fill="url(#micro-shell)"/><circle cx="420" cy="280" r="7" fill="#0a1222" stroke="#5b6b85" stroke-width="1"/><text x="420" y="458" text-anchor="middle" class="svg-label">MICROGRAVITY · ISS</text><text x="420" y="476" text-anchor="middle" class="svg-sub">Nothing rises · oxygen diffuses in</text></g></svg></div></section>${dashboardInsights()}<section id="mission-planner" class="mission-planner"><div class="planner-head"><div><div class="eyebrow">START HERE / INTERACTIVE BRIEF</div><h2>What are you trying to understand?</h2></div><p>Choose a starting point. FlameWise will lead you to the right evidence path.</p></div><div class="planner-layout"><div class="planner-options" role="group" aria-label="Choose a research path"><button class="planner-choice selected" data-home-mode="scenario" data-destination="scenario"><span>01</span><strong>Plan for a lunar habitat</strong><small>Match a mission context to available evidence</small></button><button class="planner-choice" data-home-mode="materials" data-destination="explorer"><span>02</span><strong>Study material flame spread</strong><small>Search experiments and compare conditions</small></button><button class="planner-choice" data-home-mode="question" data-destination="assistant"><span>03</span><strong>Ask a research question</strong><small>Get a cited answer from the collection</small></button></div><aside class="planner-response" aria-live="polite"><div class="response-orbit"><i></i><i></i><i></i><b>FW</b></div><div id="mission-message"><span class="response-label">RECOMMENDED PATH</span><h3>Mission scenario</h3><p>Start with the habitat, atmosphere or material you care about. FlameWise will show related evidence and the conditions that do not transfer.</p></div><a id="mission-continue" class="button" href="#scenario">Build a scenario <span>→</span></a></aside></div></section><section id="product-band" class="product-band"><div class="product-copy"><div class="eyebrow">THE FLAMEWISE METHOD</div><h2>Evidence that stays attached to its limits.</h2><p>Most dashboards stop at the chart. FlameWise keeps the research question, experimental conditions, source status and caveats together - so a fast answer never becomes a false conclusion.</p><a class="button secondary" href="#assistant">Try a cited question <span>→</span></a></div><div class="product-preview" aria-label="A preview of a FlameWise evidence result"><div class="preview-top"><span class="preview-dot"></span><span>MISSION SCENARIO / LUNAR HABITAT</span><em>Evidence match</em></div><div class="preview-question">“Which experiments help us understand plastic flame spread?”</div><div class="preview-result"><b>Relevant evidence</b><strong>BASS-II &amp; Saffire</strong><p>Microgravity data offers material and flame-spread context. It does not validate lunar partial-gravity performance.</p></div><div class="preview-gaps"><span>01</span><p><b>Gravity mismatch</b><br>Direct lunar validation unavailable</p><span>02</span><p><b>Pressure not verified</b><br>Matching oxygen alone is insufficient</p></div></div></section><section class="use-cases"><div class="use-case-title"><div class="eyebrow">BUILT FOR EXPLORATION</div><h2>One product.<br>Three ways in.</h2></div><article><span>01</span><h3>Researchers</h3><p>Trace a topic back to its experimental conditions and primary sources before making a comparison.</p></article><article><span>02</span><h3>Mission teams</h3><p>Bring a habitat scenario and see which evidence applies, which assumptions fail, and what still needs testing.</p></article><article><span>03</span><h3>Educators &amp; explorers</h3><p>Turn a difficult archive into a guided, source-backed story about fire beyond Earth.</p></article></section><section class="evidence-ledger"><div class="ledger-title"><div class="eyebrow">WHAT IS INSIDE</div><h2>A traceable research collection.</h2><p>Built from actual NASA research records and documented source material - not simulated dashboard data.</p><a href="#sources">Inspect sources & data quality →</a></div><div class="ledger-stats"><div><strong>${catalogue.investigations.length}</strong><span>NASA investigations<br>across four themes</span></div><div><strong>${csv}</strong><span>BASS-II source<br>CSV records</span></div><div><strong>${verified}</strong><span>Report-verified<br>Saffire records</span></div></div></section><section class="briefing-note"><div class="note-mark">!</div><div><div class="eyebrow">THE ESSENTIAL CAVEAT</div><h2>Microgravity evidence is not a lunar safety certificate.</h2><p>FlameWise shows where conditions overlap, where they differ and what still needs research. It does not predict fire risk or recommend safe materials.</p></div><a class="quiet-link" href="#method">Read the methodology</a></section>`;}
function strengthText(g){return [[g.verifiedRecords,'report-verified test record'],[g.quantFindings,'quantitative report finding'],[g.locatedPassages,'page-located passage']].filter(([n])=>n).map(([n,t])=>n+' '+t+(n>1?'s':'')).join(' · ')||'Qualitative source description only';}
function gapMatrix(){
 const rows=[['Prevention','Do measured spread rates, and materials that refused to spread, hold once weak buoyancy returns?'],['Detection','How does smoke travel and age when it rises slowly instead of not at all?'],['Suppression','Do cool flames and extinction behave the same way in partial gravity?'],['Fundamentals','Can models built on microgravity flames be extended to 0.17 g and 0.38 g?']];
 const cols=[['Microgravity','Microgravity','ISS and Cygnus'],['Lunar partial gravity','Moon','0.17 g'],['Martian partial gravity','Mars','0.38 g']];
 const body=rows.map(([theme,open])=>{const all=catalogue.investigations.filter(i=>i.category===theme);
  return '<tr><th scope="row">'+badge(theme)+'<small>'+esc(open)+'</small></th>'+cols.map(([gravity])=>{const inv=all.filter(i=>i.gravity===gravity),ids=inv.map(i=>i.id);const records=catalogue.tests.filter(t=>ids.includes(t.investigation)&&t.verification==='Report verified').length,findings=(catalogue.quantitativeFindings||[]).filter(f=>f.investigations.some(id=>ids.includes(id))).length;
   return inv.length?'<td class="gap-cell has-evidence"><strong>'+inv.length+'</strong><span>investigation'+(inv.length>1?'s':'')+'</span><p>'+records+' verified records · '+findings+' quantitative findings</p><div class="row-actions">'+inv.map(i=>'<button class="text-button" data-detail="'+esc(i.id)+'">'+esc(i.name)+'</button>').join('')+'</div></td>':'<td class="gap-cell no-evidence"><strong>0</strong><span>direct records</span><p>Nearest evidence: '+all.length+' microgravity investigation'+(all.length>1?'s':'')+'. Transfer untested.</p></td>';}).join('')+'</tr>';}).join('');
 return '<section class="gap-matrix"><div class="section-head"><div><div class="eyebrow">WHERE THE EVIDENCE STOPS</div><h2>Fire-safety evidence by destination.</h2><p>Every record in this collection was taken in microgravity. The hatched cells are the research still to be done before a lunar or Martian habitat can rely on it.</p></div><a href="#scenario">Test a mission scenario →</a></div><div class="table-wrap"><table class="gap-table"><thead><tr><th scope="col">Fire-safety theme and open question</th>'+cols.map(([,name,note])=>'<th scope="col">'+name+'<small>'+note+'</small></th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div><p class="note">Counts come from the catalogue: report-verified test records and quantitative report findings only. An empty cell means no direct evidence in this collection, not that the environment is safe or unsafe.</p></section>';
}
function insightsPage(){const list=catalogue.insights||[];
 return head('MISSION INSIGHTS','What the evidence says for exploration.','Six findings from NASA combustion research, each with what it means for a crew and where it stops applying.')+'<div class="notice blue">Ranked by evidence strength: how much checkable material stands behind each insight in this collection. A report-verified test record or a page-located passage counts one point, a quantitative report finding two. The order is not a ranking of danger.</div><ol class="insight-list">'+list.map((s,n)=>'<li class="panel insight"><div class="insight-rank"><b>'+(n+1)+'</b><span>of '+list.length+'</span></div><div class="insight-body"><div class="insight-tags">'+badge(s.theme)+'<span class="badge '+(s.strength.tier==='Measured'?'verified':'context')+'">'+esc(s.strength.tier)+' · strength '+s.strength.score+'</span><span class="micro muted">'+esc(strengthText(s.strength))+'</span></div><h2>'+esc(s.title)+'</h2><div class="insight-grid"><div><h3>The evidence</h3><p>'+esc(s.evidence)+'</p></div><div class="insight-meaning"><h3>What it means for a crew</h3><p>'+esc(s.meaning)+'</p></div><div><h3>Where it stops</h3><p>'+esc(s.limit)+'</p></div></div><div class="row-actions">'+s.investigations.map(id=>'<button class="text-button" data-detail="'+esc(id)+'">'+esc(getInv(id)?.name||id)+' ↗</button>').join('')+s.tests.map(id=>'<button class="text-button" data-test="'+esc(id)+'">Test '+esc(id)+' ↗</button>').join('')+'<span class="insight-sources">'+s.sources.map(sourceLink).join(' · ')+'</span><button class="button secondary" data-ask="'+esc(s.question)+'">Ask the evidence about this →</button></div></div></li>').join('')+'</ol>'+gapMatrix();}
function explorer(){return head('EVIDENCE ARCHIVE','Find the right investigation.','Search by research question, material, measurements or fire-safety goal.')+`<form id="search-form" class="searchbar"><input id="search-q" aria-label="Research question" placeholder="Try: smoke particle detection, PMMA flame spread…"><select id="category" aria-label="Fire safety theme"><option value="">All research themes</option>${['Prevention','Detection','Suppression','Fundamentals'].map(c=>`<option>${c}</option>`).join('')}</select><select id="fuel" aria-label="Fuel type"><option value="">All fuel types</option>${[...new Set(catalogue.investigations.map(i=>i.fuel))].map(f=>`<option>${esc(f)}</option>`).join('')}</select><button type="submit" class="button">Search →</button></form><div class="notice blue">Ranking shows topic relevance, not danger, reliability or NASA ratings. Specific terms outweigh common terms. Metadata matches outweigh description matches. Missing conditions are not assumed.</div><div class="browse-toolbar"><div id="filter-chips" class="filter-chips"></div><div class="view-switch" role="group" aria-label="Investigation layout"><button data-view="cards" aria-pressed="${explorerView==='cards'}">Cards</button><button data-view="list" aria-pressed="${explorerView==='list'}">List</button><button id="reset-filters">Reset filters</button></div></div><section id="search-summary" class="panel search-summary" aria-live="polite" hidden></section><div id="results-info" class="result-info"></div><div id="results" class="grid"></div><div id="compare-holder"></div><section id="passage-results" class="panel" hidden></section>`;}
let summaryVersion=0;
async function summarize(q){const el=$('#search-summary'),version=++summaryVersion;if(!el)return;q=String(q||'').trim();if(!q){el.hidden=true;el.innerHTML='';return;}
 el.hidden=false;el.classList.add('loading');el.innerHTML='<div class="answer-head"><h2>Evidence summary</h2><span class="badge">Reading the evidence…</span></div><div class="summary-skeleton"><i></i><i></i><i></i></div>';
 try{const data=await request('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q})});if(version!==summaryVersion||activePage!=='explorer')return;
  if(data.mode==='AI synthesis')aiSessionStatus='success';else if(data.notice)aiSessionStatus='fallback';
  el.classList.remove('loading');el.innerHTML='<div class="answer-head"><h2>Evidence summary</h2><span class="badge '+(data.mode==='AI synthesis'?'':'detection')+'">'+esc(data.mode)+'</span></div>'+(data.notice?'<div class="notice">'+esc(data.notice)+'</div>':'')+'<div class="answer">'+renderAnswerText(data.answer,data.citations)+'</div><div class="citations">'+(data.citations||[]).map((id,n)=>'<span class="numbered-source">'+(n+1)+'. '+sourceLink(id)+'</span>').join('')+'</div>'+(data.limitations?.length?'<p class="note">'+esc(data.limitations[0])+'</p>':'')+'<div class="row-actions"><button class="text-button" id="open-summary">Open the full answer with evidence →</button></div>';
  currentSummary={...data,question:q};
 }catch(e){if(version!==summaryVersion)return;el.classList.remove('loading');el.innerHTML='<div class="notice">Summary unavailable: '+esc(e.message)+'. The ranked results below still apply.</div>';}}
let currentSummary=null;
async function runSearch(){const version=++searchVersion;try{const q=$('#search-q').value;const p=new URLSearchParams({q,category:$('#category').value,fuel:$('#fuel').value});const {results,passages}=await request('/api/search?'+p);if(activePage!=='explorer'||version!==searchVersion)return;$('#results-info').innerHTML=`<span>${results.length} matching investigations</span><span>${q?'Sorted by topic relevance':'Alphabetical · no question entered'}</span>`;$('#results').className=explorerView==='list'?'investigation-list':'grid';document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===explorerView)));$('#filter-chips').innerHTML=[['search-q',q],['category',$('#category').value],['fuel',$('#fuel').value]].filter(([,v])=>v).map(([id,v])=>'<button class="filter-chip" data-clear-filter="'+id+'" aria-label="Remove '+esc(v)+' filter">'+esc(v)+' ×</button>').join('');$('#results').innerHTML=results.length?results.map(i=>card(i,i.reasons.length?`<div class="reason">${esc(i.reasons.slice(0,3).join(' · '))}<br>Topic points: ${i.score} · Verified records: ${i.evidenceRecords}<br>${esc(i.coverageStatus)}</div>`:'')).join(''):'<div class="empty"><h3>No matching evidence</h3><p>Try a broader term or clear the filters.</p></div>';$('#compare-holder').innerHTML=comparisonBar();$('#passage-results').hidden=!passages?.length;$('#passage-results').innerHTML=passageHTML(passages);}catch(e){toast(e.message);}}
function compare(){const ids=[...selected];const items=ids.map(getInv);return head('COMPARE & UNDERSTAND','Put the evidence side by side.','Compare research scope and conditions before comparing findings.',`<a href="#explorer" class="button secondary">Choose investigations ↗</a>`)+(items.length<2?`<div class="empty"><h3>Select at least two investigations</h3><p>Choose up to three in the Investigation Explorer.</p><a class="button" href="#explorer">Select investigations →</a></div>`:`<div class="notice warning">${new Set(items.map(i=>i.fuel)).size>1?'Different fuel regimes selected: qualitative comparison only. Numerical pooling is unsupported.':'Even with the same fuel class, geometry, scale and atmosphere may differ.'} Missing conditions do not establish equivalence.</div><div class="table-wrap comparison-table"><table><thead><tr><th>Attribute</th>${items.map(i=>`<th>${esc(i.name)} <button class="text-button" data-remove="${i.id}" aria-label="Remove ${i.name}">×</button></th>`).join('')}</tr></thead><tbody>${[['Research theme',i=>i.category],['Summary',i=>i.summary],['Finding / evidence status',i=>i.finding],['Fuel',i=>i.fuel],['Materials',i=>i.materials.join(', ')],['Gravity',i=>i.gravity],['Platform',i=>i.platform],['Hardware',i=>i.hardware],['Recorded conditions',i=>i.conditions],['Measurements',i=>i.measurements.join(', ')],['Data included',i=>i.coverage],['Limitations',i=>i.limitations.join(' ')],['Sources',i=>i.sources.map(sourceLink).join('<br>')]].map(([label,fn])=>`<tr class="${new Set(items.map(fn)).size>1?'diff-row':'same-row'}"><th>${label}${new Set(items.map(fn)).size>1?'<small>Differs</small>':''}</th>${items.map(i=>`<td class="wrap">${label==='Sources'?fn(i):esc(fn(i))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice blue">Different hardware and sample scales prevent a direct universal flammability ranking. These summaries are not a meta-analysis.</div>`);}

function quantitativeHTML(id){const rows=(catalogue.quantitativeFindings||[]).filter(f=>!id||f.investigations.includes(id));return rows.length?'<section class="panel"><h2>Quantitative report findings</h2><p class="note">Report-level findings, separate from individual test records. Ranges and ratios must not be pooled as equivalent measurements.</p>'+rows.map(f=>'<article class="source-card"><h3>'+esc(f.title)+'</h3><strong>'+esc(f.range?f.range.join('–'):f.value)+' '+esc(f.unit)+'</strong><p>'+esc(f.text)+'</p><p>'+esc(f.conditions)+'</p><p class="note">'+esc(f.scope)+' · '+esc(f.limitations)+'</p>'+sourceLink(f.source)+' · <a target="_blank" rel="noopener noreferrer" href="'+esc(getSource(f.source).url)+'#page='+f.page+'">'+esc(f.location)+' ↗</a></article>').join('')+'<p class="note">FLEX currently has qualitative cool-flame findings only. Quantitative extinction and suppressant datasets remain to be verified.</p></section>':'';}

function qualityReviewHTML(){const rows=catalogue.tests.filter(t=>t.investigation==='bass2');const checks=[['Negative CO sensor reading','Negative CO values','Retained as source readings. Do not clamp to zero or interpret as negative emissions. Offset correction requires instrument documentation.'],['Unusual oxygen change','Unusual oxygen changes','Retained and excluded from safety conclusions. A transcription match does not resolve calibration or test-sequence effects.'],['Air display contains','Changing fan settings','These are settings or sequences, not a verified scalar velocity. No global cm/s conversion is applied.'],['Material identity incomplete','Incomplete material descriptions','Preserve the source wording. Material identity requires the test matrix or sample documentation.'],['Date and GMT','Date / GMT disagreement','Both source fields remain unchanged; chronology is unresolved.'],['Date year differs','Unexpected year','Source year retained. Do not silently assume a corrected date.']];return '<section class="panel"><div class="eyebrow">BASS-II / DATA REVIEW</div><h2>Flagged readings</h2><p>Interpretation status: pending full report, readme and fan-calibration review. Counts overlap across issues.</p><div class="table-wrap"><table><thead><tr><th>Issue</th><th>Records</th><th>Handling</th></tr></thead><tbody>'+checks.map(([flag,label,note])=>'<tr><td>'+label+'</td><td>'+rows.filter(t=>t.flags.some(f=>f.includes(flag))).length+'</td><td class="wrap">'+note+'</td></tr>').join('')+'</tbody></table></div><p class="note">Missing, censored and over-range values remain null numerically, with the original text retained. Enable the source CSV records below and open any test to inspect its raw values and flags.</p></section>';}
function lab(){return head('INSPECT THE MEASUREMENTS','Data laboratory.','A small, traceable numerical subset. Every chart point opens its test record.')+`<div class="notice blue">Seven report-verified Saffire condition records. Optional BASS-II CSV: 129 nonempty records verified against the NASA table; one blank trailing entry explains its count of 130. Sensor interpretation and airflow conversion remain unverified.</div><div class="searchbar"><input id="test-q" aria-label="Filter test records" placeholder="Filter by test ID, material, observation or flag"><select id="test-investigation" aria-label="Filter investigation"><option value="">All included investigations</option>${['saffire1','saffire2','bass2'].map(id=>`<option value="${id}">${getInv(id).name}</option>`).join('')}</select><label class="check"><input type="checkbox" id="include-preview"> Include source CSV (interpretation pending)</label><button id="export-json" class="button secondary">↓ JSON + citations</button><button id="export-csv">↓ CSV</button></div><section class="panel"><div class="split-title"><div><div class="eyebrow">REPORTED CONDITIONS · VERIFIED RECORDS ONLY</div><h2 id="chart-title">Oxygen concentration × airflow</h2></div><span class="pill">NOT A RISK MAP</span></div><div class="chart-controls"><label>Plot <select id="chart-metric" aria-label="Chart metric"><option value="conditions">Oxygen × airflow</option><option value="spread_rate_mms">Flame spread rate</option><option value="burn_duration_s">Burn duration</option></select></label><span id="chart-tooltip" role="status" aria-live="polite">Hover or focus a point, bar or table row for details.</span></div><div id="chart"></div><div class="legend"><span><b></b>Silicone</span><span><b class="blue-dot"></b>SIBAL fabric</span></div><p class="chart-description">Point positions represent reported conditions, not flame intensity or safety. Identical conditions share a marker; buttons below expose every record. Oxygen readings are identified as ISS readings in the source.</p></section><details class="panel"><summary>Quantitative report findings</summary>${quantitativeHTML()}</details><details class="panel"><summary>Data quality and flagged readings</summary>${qualityReviewHTML()}</details><div id="lab-count" class="result-info"></div><div id="test-table"></div><section class="panel"><h2>Compare individual tests</h2><div id="test-comparison">Select two or three tests in the table.</div></section>`;}
function drawChart(rows){const all=rows.filter(t=>t.verification==='Report verified'&&t.airflow_cms!=null&&t.oxygen_initial_pct!=null);if(!all.length)return '<div class="empty">No verified oxygen/airflow pairs in this selection.</div>';const x=v=>70+(v/30)*700;const y=v=>260-((v-20)/3)*210;return `<svg class="chart" viewBox="0 0 830 320" role="img" aria-label="Verified Saffire oxygen concentration versus airflow chart; equivalent records available in table"><text x="10" y="18">O₂ (volume %)</text>${[20,21,22,23].map(v=>`<line class="gridline" x1="70" y1="${y(v)}" x2="770" y2="${y(v)}"/><text x="35" y="${y(v)+4}">${v}</text>`).join('')}${[0,5,10,15,20,25,30].map(v=>`<text x="${x(v)-5}" y="284">${v}</text>`).join('')}<text x="355" y="313">Airflow (cm/s)</text>${all.filter((t,index)=>all.findIndex(r=>r.airflow_cms===t.airflow_cms&&r.oxygen_initial_pct===t.oxygen_initial_pct)===index).map(t=>`<circle tabindex="0" role="button" aria-label="Open test ${t.id}" data-test="${t.id}" data-highlight="${t.id}" data-condition="${t.airflow_cms}|${t.oxygen_initial_pct}" class="dot ${t.material.includes('SIBAL')?'fabric':''}" cx="${x(t.airflow_cms)}" cy="${y(t.oxygen_initial_pct)}" r="8"><title>${t.id}: ${t.material}, ${t.oxygen_initial_pct}% O₂, ${t.airflow_cms} cm/s</title></circle>`).join('')}</svg><div class="row-actions">${all.map(t=>`<button data-test="${t.id}" data-highlight="${t.id}">${esc(t.id)} · ${t.oxygen_initial_pct}% / ${t.airflow_cms} cm/s</button>`).join('')}</div>`;}
function updateLab(){labRows=catalogue.tests.filter(t=>($('#include-preview').checked||t.verification==='Report verified')&&(!$('#test-investigation').value||t.investigation===$('#test-investigation').value)&&[t.id,t.raw_material,t.outcome,...t.flags].join(' ').toLowerCase().includes($('#test-q').value.toLowerCase()));$('#chart-title').textContent=chartMetric==='conditions'?'Oxygen concentration × airflow':chartMetric==='spread_rate_mms'?'Reported flame spread rates (mm/s)':'Reported burn durations (s)';$('#chart').innerHTML=chartMetric==='conditions'?drawChart(labRows):resultsChart(labRows,chartMetric);$('#lab-count').innerHTML=`<span>${labRows.length} records · ${labRows.filter(t=>t.verification==='Report verified').length} report-verified</span><span>— = not reported / not verified</span>`;$('#test-table').innerHTML=labRows.length?`<div class="table-wrap"><table><thead><tr><th>Compare</th><th>Test / source</th><th>Material (raw description)</th><th>Thickness mm</th><th>O₂ initial %</th><th>Airflow cm/s</th><th>Air display*</th><th>CO initial → final ppm</th><th>Observation</th><th>Verification</th></tr></thead><tbody>${labRows.map(t=>`<tr data-highlight="${esc(t.id)}" tabindex="0"><td><input type="checkbox" aria-label="Compare test ${esc(t.id)}" data-test-select="${esc(t.id)}" ${selectedTests.has(t.id)?'checked':''}></td><td><button class="text-button" data-test="${t.id}">${t.id} ↗</button><br><span class="micro muted">${getInv(t.investigation).name}</span></td><td class="wrap">${esc(t.raw_material)}</td><td>${t.thickness_mm??'—'}</td><td>${t.oxygen_initial_pct??'—'}</td><td>${t.airflow_cms??'—'}</td><td>${t.air_display??'—'}</td><td>${t.co_initial_ppm??'—'} → ${t.co_final_ppm??'—'}</td><td class="wrap">${esc(t.outcome)}${t.spread_rate_mms!=null?'<br>'+t.spread_rate_mms+' mm/s · '+t.burn_duration_s+' s':''}</td><td><span class="badge ${t.verification==='Report verified'?'verified':'warning source-transcribed'}">${t.verification==='Report verified'?'Report-verified':'Source-transcribed · interpretation pending'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No records match these filters.</div>';}
function testComparison(){const rows=[...selectedTests].map(id=>catalogue.tests.find(t=>t.id===id));const el=$('#test-comparison');if(!el)return;el.innerHTML=rows.length<2?'Select at least two tests.':'<div class="notice">Geometry, atmosphere and verification may differ. These records do not establish material safety.</div><div class="table-wrap"><table><thead><tr><th>Field</th>'+rows.map(t=>'<th>'+esc(t.id)+'</th>').join('')+'</tr></thead><tbody>'+['raw_material','thickness_mm','oxygen_initial_pct','airflow_cms','spread_rate_mms','burn_duration_s','outcome','verification','location'].map(k=>'<tr><th>'+esc(k)+'</th>'+rows.map(t=>'<td class="wrap">'+esc(t[k]??'Not reported / not verified')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function outcomeChart(){const rows=labRows.filter(t=>t.spread_rate_mms!=null);return '<h3>Reported flame spread rates (mm/s)</h3><p class="note">Different sample scale, oxygen and airflow: descriptive measurements, not a controlled causal comparison.</p>'+rows.map(t=>'<div class="measurement"><button class="text-button" data-test="'+t.id+'">'+esc(t.id)+'</button><meter min="0" max="3" value="'+t.spread_rate_mms+'">'+t.spread_rate_mms+'</meter><span>'+t.spread_rate_mms+' mm/s · '+esc(t.measurement_location)+'</span></div>').join('');}
function scenario(){return head('MATCH CONDITIONS. EXPOSE GAPS.','Explore a research scenario.','Locate relevant evidence without assuming that similar conditions establish safety.')+`<form id="scenario-form" class="panel field-grid"><label class="full">Research question<input name="q" placeholder="e.g. plastic flame spread in a lunar habitat"></label><label>Research goal<select name="category"><option value="">Any theme</option><option>Prevention</option><option>Detection</option><option>Suppression</option></select></label><label>Target gravity<select name="gravity"><option>Microgravity</option><option>Lunar partial gravity</option><option>Martian partial gravity</option><option>Earth gravity</option></select></label><label>Material<input name="material" placeholder="e.g. PMMA"></label><label>Oxygen (% by volume)<input name="oxygen" type="number" min="0" max="100" step="any" placeholder="Not specified"></label><label>Pressure (kPa)<input name="pressure" type="number" min="0" max="10000" step="any" placeholder="Not specified"></label><label>Airflow (cm/s)<input name="airflow" type="number" min="0" max="10000" step="any" placeholder="Not specified"></label><div class="full"><button class="button" type="submit">Find evidence & gaps →</button></div></form><div class="notice">No direct partial-gravity validation is included. Numerical condition overlap is descriptive, not a safety recommendation.</div><div id="scenario-results" class="grid"></div>`;}
function assistant(){return head('RESEARCH / QUESTIONS','Ask the evidence.','Answers grounded in the curated investigation catalogue and included test records.')+`<div class="ask-layout"><div><form id="ask-form" class="panel question-panel"><div class="answer-head"><h2>Your research question</h2><span class="badge" id="ai-status" role="status" aria-live="polite">${esc(aiStatusText())}</span></div><label class="sr-only" for="question">Research question</label><textarea id="question" maxlength="2000" placeholder="Which investigations are relevant to smoke detection in a spacecraft?"></textarea><div class="prompts">${['Smoke particle detection','Compare B1 and B4','Which tests have higher final CO?','Droplet suppression research','Is PMMA safe on the Moon?'].map(q=>`<button type="button" data-prompt="${q}">${q}</button>`).join('')}</div><button type="submit" class="button" id="ask-button">Find an evidence-backed answer →</button></form><div id="answer-panel" class="panel answer-panel" hidden></div></div><aside class="panel"><div class="eyebrow">HOW ANSWERS WORK</div><h2>Sources before synthesis.</h2><div class="step"><span class="step-number">01</span><p>Retrieve matching investigations and relevant test records.</p></div><div class="step"><span class="step-number">02</span><p>${health.aiConfigured?'A configured server-side model can synthesize supplied evidence. Paragraph citations are checked; the response mode confirms whether synthesis succeeded.':'Without an API key, return labeled, deterministic evidence summaries. This is not live LLM generation.'}</p></div><div class="step"><span class="step-number">03</span><p>Follow the source links. Review omissions and applicability before drawing conclusions.</p></div><div class="notice">The collection cannot establish safe operating thresholds, certified materials or fire probabilities.</div><a href="#method">Read answer methodology →</a></aside></div>`;}
function showAnswer(data){currentAnswer=data;if(data.mode==='AI synthesis')aiSessionStatus='success';else if(data.notice)aiSessionStatus='fallback';const status=$('#ai-status');if(status)status.textContent=aiStatusText();if(!$('#answer-panel'))return;$('#answer-panel').hidden=false;$('#answer-panel').innerHTML=`<div class="answer-head"><h2>Evidence response</h2><span class="badge ${data.mode==='AI synthesis'?'':'detection'}">${esc(data.mode)}</span></div>${data.notice?`<div class="notice">${esc(data.notice)}</div>`:''}<div class="answer">${renderAnswerText(data.answer,data.citations)}</div><div class="citations">${(data.citations||[]).map((id,n)=>'<span class="numbered-source">'+(n+1)+'. '+sourceLink(id)+'</span>').join('')}</div>${data.passages?.length?'<details class="answer-evidence"><summary>Supporting evidence ('+data.passages.length+')</summary>'+passageHTML(data.passages)+'</details>':''}${data.limitations?.length?`<details class="answer-evidence"><summary>Limitations</summary><ul class="gap-list">${data.limitations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`:''}<div class="row-actions">${(data.matches||[]).map(id=>`<button class="text-button" data-detail="${id}">${getInv(id)?.name||id} ↗</button>`).join('')}<button class="text-button" id="save-answer">↓ Save response + sources</button></div>`;}
function sourceCard(s){return `<article class="source-card"><div class="source-meta"><span>${esc(s.role)}</span><strong>${esc(s.status)}</strong></div><h3>${sourceLink(s.id)}</h3><p>${esc(s.note)}</p>${s.doi?`<a class="micro" href="https://doi.org/${esc(s.doi)}" target="_blank" rel="noopener noreferrer">DOI: ${esc(s.doi)}</a>`:''}</article>`;}
function sourcesPage(){return head('COLLECTION / REFERENCES','Every insight needs a source.','All challenge-provided resources are included below, with the scope of our access made explicit.')+`<div class="notice blue">“Reviewed” means the listed page or identified report passages were inspected. It does not mean every attached dataset was ingested. The introductory video could not be accessed; no transcript was used.</div><div class="source-columns"><section class="panel"><h2>Research & experimental evidence</h2>${catalogue.sources.filter(s=>!['Historical context','Earth application'].includes(s.role)).map(sourceCard).join('')}</section><div><section class="panel"><h2>Why crew fire safety matters</h2><p>Apollo 1, Apollo 13 and Mir offer historical context. These incidents are not numerical inputs to the experiment charts.</p>${catalogue.sources.filter(s=>s.role==='Historical context').map(sourceCard).join('')}</section><section class="panel section-head"><div><h2>From space to Earth</h2><p>Technology transfer examples, not proof of a causal link to the included combustion tests.</p>${catalogue.sources.filter(s=>s.role==='Earth application').map(sourceCard).join('')}</div></section></div></div>`;}
function method(){return head('TRANSPARENT BY DESIGN','Methodology & limitations.','What is measured, what is curated, and what remains unknown.')+`<div class="two-col"><section class="panel"><h2>Collection and provenance</h2><p>Investigation summaries are manually curated paraphrases of official NASA pages, indexed metadata and identified reports. Seven Saffire condition records are transcribed from the 2017 presentation. 129 BASS-II rows were imported from the NASA CSV. The page lists 130 entries because it includes a blank trailing row. All 129 nonempty records match the imported CSV. Raw transcription is verified. The source labels oxygen columns calibrated; independent interpretation of the readings remains pending.</p><h3>Raw and normalized values</h3><p>Original material strings are preserved. Thickness in microns is normalized to millimetres. Unknown material identity is not filled in. Null means unavailable or unverified, not zero. B2’s unusual oxygen value and B4’s negative CO reading remain unchanged with flags.</p><h3>Ranking</h3><p>Rarer terms receive more weight. Metadata matches count three times description matches. Scenario material overlap adds three points and each numerical condition overlap adds one; completeness is reported separately. Filters narrow the candidates. No match returns no evidence. These points are project heuristics, not probabilities, quality ratings or NASA scores.</p><h3>Comparison</h3><p>Investigation comparisons are qualitative. Different fuels, geometries, hardware and scale prevent direct pooling. Condition charts show reported atmospheres and flow; outcome charts show selected spread rates. Different configurations are not controlled causal comparisons. Table records provide the accessible alternative.</p><h3>Exports</h3><p>JSON bundles contain units, source URLs, verification state and limitations. CSV preserves nulls as empty cells; pair it with the JSON manifest for provenance.</p></section><section class="panel"><h2>Answering and applicability</h2><p>Default mode is deterministic retrieval with source links. Optional server-side Gemini, OpenAI or Anthropic integration can synthesize retrieved records. Invalid citations or provider failures trigger a labeled retrieval fallback. Citation structure checks do not guarantee that claims are supported by sources.</p><h3>What this cannot establish</h3><ul><li>Safe material certification or operational suppression doses.</li><li>Validated lunar or Martian partial-gravity behavior.</li><li>Fire probability or a universal danger score.</li><li>Predictive performance: no predictive model is trained.</li><li>Test outcomes absent from the inspected sources.</li></ul><h3>Current gaps</h3><p>Bulk PSI files are not ingested. A readme and fan-calibration workbook are listed in PSI, but their downloads did not complete during verification. The full downloaded BASS-II CSV is included, with 129 rows and raw fields retained. The collection is not automatically synchronized with PSI. Saffire-III includes a source-located duration finding. SAME and SAME-R share explicitly labeled combined-flight report findings; individual smoke measurements are not ingested.</p><h3>Attribution</h3><p>Use the original investigation citation and DOI for research. BASS-II metadata lists CC0-1.0; source-specific terms still apply to other resources. This independent project is not endorsed by NASA.</p><a href="#sources">Inspect the source audit →</a></section></div>`;}
function details(id){const i=getInv(id);if(!i)return;$('#detail').classList.add('evidence-drawer');$('#detail-body').innerHTML=`<div class="drawer-kicker">INVESTIGATION / EVIDENCE</div>${badge(i.category)}<h1>${esc(i.name)}</h1><p class="subtitle">${esc(i.fullName)}</p><p>${esc(i.summary)}</p><details><summary>Research objective / scope</summary><p>${esc(i.objective||i.summary)}</p></details><h3>Findings</h3>${evidenceStatus(i)}<span class="badge">${esc(i.findingStatus||'Investigation summary')}</span><p>${esc(i.finding)}</p><h3>Conditions & measurements</h3><dl class="detail-grid">${[['Fuel',i.fuel],['Materials',i.materials.join(', ')],['Gravity',i.gravity],['Hardware',i.hardware],['Platform',i.platform],['Data coverage',i.coverage],['Measurements',i.measurements.join(', ')],['Conditions',i.conditions]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${quantitativeHTML(i.id)}${passageHTML((catalogue.passages||[]).filter(p=>p.investigation===i.id))}<details><summary>Evidence boundaries & limitations</summary><ul>${i.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></details><h3>Original sources</h3><div class="citations">${i.sources.map(sourceLink).join('')}</div><p class="note">Summaries are project-authored paraphrases. Follow original sources for complete methods and results.</p>`;$('#detail').showModal();$('#detail').scrollTop=0;}
function testDetails(id){const t=catalogue.tests.find(t=>t.id===id);if(!t)return;$('#detail').classList.add('evidence-drawer');$('#detail-body').innerHTML=`<span class="badge ${t.verification==='Report verified'?'verified':'warning source-transcribed'}">${t.verification==='Report verified'?'Report-verified':'Source-transcribed · interpretation pending'}</span><h1>Test ${esc(t.id)}</h1><p>${esc(t.raw_material)}</p><div class="notice">${esc(t.outcome)}</div><dl class="detail-grid">${Object.entries(t).filter(([k])=>!['raw_material','outcome','flags','raw','field_provenance'].includes(k)).map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(v??'Not reported / not verified')}</dd></div>`).join('')}</dl>${t.field_provenance?'<h3>Field source locations</h3><ul>'+Object.entries(t.field_provenance).map(([field,location])=>'<li>'+esc(field)+': '+esc(location)+'</li>').join('')+'</ul>':''}${t.flags.length?`<h3>Quality flags</h3><ul>${t.flags.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}<div class="citations">${sourceLink(t.source)}</div><p class="note">${esc(t.location)}. Unknown fields must not be treated as zero.</p>${t.raw?'<details><summary>Original CSV fields</summary><pre class="raw-data">'+esc(JSON.stringify(t.raw,null,2))+'</pre></details>':''}`;$('#detail').showModal();$('#detail').scrollTop=0;}
async function render(){activePage=location.hash.slice(1)||'overview';if(!titles[activePage])activePage='overview';const crumb=$('#breadcrumb');if(crumb)crumb.textContent=titles[activePage];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===activePage);if(a.dataset.page===activePage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const pages={overview:briefing,insights:insightsPage,dashboard:overview,explorer,compare,lab,scenario,assistant,sources:sourcesPage,method};$('#page').innerHTML=pages[activePage]();restore();if(activePage==='explorer')await runSearch();if(activePage==='lab'){updateLab();testComparison();}if(activePage==='assistant'&&currentAnswer)showAnswer(currentAnswer);if(activePage==='assistant'&&pendingAsk){pendingAsk=false;$('#ask-form').requestSubmit?.();}window.scrollTo(0,0);}
function highlightRecord(id){const t=catalogue.tests.find(t=>t.id===id);document.querySelectorAll('[data-highlight]').forEach(el=>{const row=catalogue.tests.find(r=>r.id===el.dataset.highlight);const shared=el.dataset.condition&&t&&row&&row.airflow_cms===t.airflow_cms&&row.oxygen_initial_pct===t.oxygen_initial_pct;el.classList.toggle('linked-active',el.dataset.highlight===id||Boolean(shared));});const tip=$('#chart-tooltip');if(t&&tip)tip.textContent=t.id+' · '+t.raw_material+' · O₂ '+(t.oxygen_initial_pct??'—')+'% · airflow '+(t.airflow_cms??'unverified')+(t.airflow_cms!=null?' cm/s':'')+' · '+t.verification;}
for(const event of ['pointerover','focusin'])document.addEventListener(event,e=>{const el=e.target.closest('[data-highlight]');if(el)highlightRecord(el.dataset.highlight);});
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]'),chip=e.target.closest('[data-clear-filter]');if(view){explorerView=view.dataset.view;runSearch();}if(chip){$('#'+chip.dataset.clearFilter).value='';remember();runSearch();}if(e.target.id==='open-summary'&&currentSummary){currentAnswer=currentSummary;drafts.assistant={question:{value:currentSummary.question}};location.hash='#assistant';}if(e.target.id==='reset-filters'){summarize('');for(const id of ['search-q','category','fuel'])$('#'+id).value='';remember();runSearch();}});
document.addEventListener('click',async e=>{const d=e.target.closest('[data-detail]'),t=e.target.closest('[data-test]'),p=e.target.closest('[data-prompt]'),r=e.target.closest('[data-remove]');if(d)details(d.dataset.detail);if(t)testDetails(t.dataset.test);if(p){$('#question').value=p.dataset.prompt;remember();$('#question').focus();}if(r){selected.delete(r.dataset.remove);render();}if(e.target.id==='close-detail')$('#detail').close();const ask=e.target.closest('[data-ask]');if(ask){drafts.assistant={question:{value:ask.dataset.ask}};currentAnswer=null;pendingAsk=true;location.hash='#assistant';}if(e.target.id==='export-all'){const data=await request('/api/export');saveFile('flamewise-evidence.json',JSON.stringify(data,null,2));toast('Verified records and citation manifest exported');}if(e.target.id==='export-json'){const manifest=await request('/api/export?preview=true');manifest.records=labRows;manifest.citations=catalogue.sources.filter(s=>labRows.some(r=>r.source===s.id)||(manifest.quantitativeFindings||[]).some(f=>f.source===s.id));saveFile('flamewise-filtered-evidence.json',JSON.stringify(manifest,null,2));}if(e.target.id==='export-csv'){const keys=[...new Set(labRows.flatMap(r=>Object.keys(r)))];const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';saveFile('flamewise-records.csv',keys.map(cell).join(',')+'\r\n'+labRows.map(r=>keys.map(k=>cell(Array.isArray(r[k])?r[k].join('; '):typeof r[k]==='object'&&r[k]!==null?JSON.stringify(r[k]):r[k])).join(',')).join('\r\n'),'text/csv');}if(e.target.id==='save-answer')saveFile('flamewise-response.json',JSON.stringify({...currentAnswer,sources:catalogue.sources.filter(s=>currentAnswer.citations.includes(s.id))},null,2));});
document.addEventListener('change',e=>{remember();if(e.target.id==='chart-metric'){chartMetric=e.target.value;updateLab();}if(e.target.dataset.testSelect){if(e.target.checked&&selectedTests.size>=3){e.target.checked=false;toast('Select up to three tests');return;}e.target.checked?selectedTests.add(e.target.dataset.testSelect):selectedTests.delete(e.target.dataset.testSelect);testComparison();}if(e.target.dataset.select){if(e.target.checked&&selected.size>=3){e.target.checked=false;toast('Compare up to three investigations at a time');return;}e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);if(activePage==='explorer')$('#compare-holder').innerHTML=comparisonBar();toast(selected.size+' investigations selected');}if(['test-investigation','include-preview'].includes(e.target.id))updateLab();if(['category','fuel'].includes(e.target.id))runSearch();});
document.addEventListener('input',e=>{remember();if(e.target.id==='test-q')updateLab();if(e.target.id==='search-q'){clearTimeout(searchTimer);searchTimer=setTimeout(runSearch,220);}});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-test]')&&['Enter',' '].includes(e.key)){e.preventDefault();testDetails(e.target.dataset.test);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='search-form'){summarize($('#search-q').value);return runSearch();}if(e.target.id==='scenario-form'){const button=e.target.querySelector('button');button.disabled=true;try{const data=await request('/api/scenario',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#scenario-results').innerHTML=data.results.length?data.results.map(i=>card(i,`<div class="reason">${esc(i.reasons.join(" · "))}<br>${esc(i.conditionReasons.join(" · "))}<br>${esc(i.coverageStatus)}</div><ul class="gap-list">${i.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>`)).join(''):'<div class="empty">No evidence matches the selected topic and theme. Broaden your question.</div>';}catch(err){toast(err.message);}finally{button.disabled=false;}}if(e.target.id==='ask-form'){const button=$('#ask-button');button.disabled=true;button.textContent='Retrieving evidence…';try{showAnswer(await request('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('#question').value})}));}catch(err){toast(err.message);}finally{button.disabled=false;button.textContent='Find an evidence-backed answer →';}}});
window.addEventListener('hashchange',()=>catalogue&&(document.startViewTransition?document.startViewTransition(render):render()));
document.addEventListener('click',e=>{const choice=e.target.closest('[data-home-mode]');if(!choice)return;document.querySelectorAll('.planner-choice').forEach(button=>button.classList.toggle('selected',button===choice));const content={scenario:['Mission scenario','Start with the habitat, atmosphere or material you care about. FlameWise will show related evidence and the conditions that do not transfer.','Build a scenario'],materials:['Evidence archive','Search real investigations by material, flame behavior or measurement, then compare their experimental conditions.','Explore investigations'],question:['Ask the evidence','Ask a focused question and inspect the source-backed answer, citations and limitations before drawing a conclusion.','Ask a question']}[choice.dataset.homeMode];const message=$('#mission-message'),link=$('#mission-continue');if(message){message.innerHTML='<span class="response-label">RECOMMENDED PATH</span><h3>'+content[0]+'</h3><p>'+content[1]+'</p>';link.href='#'+choice.dataset.destination;link.innerHTML=content[2]+' <span>→</span>';message.animate?.([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:320,easing:'ease-out'});}});
Promise.all([request('/api/catalogue'),request('/api/health')]).then(([c,h])=>{catalogue=c;health=h;$('#loading').remove();render();}).catch(e=>{$('#loading').innerHTML=`Unable to load the catalogue: ${esc(e.message)}. Refresh to retry.`;});
